using System.IO;
using UnityEditor;
using UnityEditor.Build;
using UnityEditor.Build.Reporting;
using UnityEditor.SceneManagement;
using UnityEngine;

namespace GrandLife {
    // A real, enabled startup scene is essential for Cloud Build.
    // The city is then generated by GL4World when that scene starts.
    [InitializeOnLoad]
    public static class Stage4AutoScene {
        public const string ScenePath = "Assets/Scenes/GrandLife_Stage4.unity";
        static Stage4AutoScene(){EditorApplication.delayCall += Ensure;}
        [MenuItem("GrandLife/Stage 4/Prepare Android Build Scene")]
        public static void Ensure(){
            if(!Directory.Exists("Assets/Scenes"))Directory.CreateDirectory("Assets/Scenes");
            if(!File.Exists(ScenePath)){
                var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);
                EditorSceneManager.SaveScene(scene,ScenePath);
                Debug.Log("GrandLife Stage 4: created startup scene " + ScenePath);
            }
            EditorBuildSettings.scenes = new[]{new EditorBuildSettingsScene(ScenePath,true)};
            PlayerSettings.companyName="GrandLife Prototype";
            PlayerSettings.productName="Grand Life RP Stage 4";
            PlayerSettings.bundleVersion="0.4.0";
            PlayerSettings.defaultInterfaceOrientation=UIOrientation.LandscapeLeft;
            PlayerSettings.SetApplicationIdentifier(BuildTargetGroup.Android,"com.grandlife.rp.prototype");
            AssetDatabase.SaveAssets();
        }
    }
    public class Stage4PreBuild : IPreprocessBuildWithReport {
        public int callbackOrder {get{return -1000;}}
        public void OnPreprocessBuild(BuildReport report){
            Stage4AutoScene.Ensure();
            Debug.Log("GrandLife Stage 4: scene verified for "+report.summary.platform);
        }
    }
}
